/* Real-card data, taken from mip diagnostic dumps (missing levels pointed at poison, the last map, or NULL) of a PCI Rage Pro
 * (1002:4750, ATI3DCIF 4.11.2692 mip-disable bug patched). Do not edit. */
struct mip_chain_layout {
    const char *mode;
    int test;
    int wl2, hl2, supplied;
    unsigned tex_off[9]; /* TEX_0_OFF..TEX_8_OFF as the driver wrote them */
    unsigned tex_size_pitch;
};

struct mip_chain_vector {
    int layout;
    int tex; /* 0 solid colour per level, 1 gray ramp */
    int filter;
    unsigned scale_3d_cntl, tex_cntl;
    double x[3], y[3], u[3], v[3], w[3];
    struct { int x, y; unsigned pixel555; } probe[3];
};

